"use client";

import { useEffect, useMemo, useState } from "react";
import { z } from "zod";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { createClient } from "@supabase/supabase-js";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Plus, Pencil, Trash2 } from "lucide-react";

// ---------------- Types ----------------
// FormValues generated from Zod
export type FormValues = z.infer<typeof schema>;

interface TrainingMethod {
  id: number;
  name: string;
  description?: string | null;
  subcapability_id: number;
}

interface Subcapability {
  id: number;
  name: string;
}

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
);

// ---------------- Schema ----------------
const schema = z.object({
  id: z.number().int().positive().optional(),
  name: z.string().min(2, "Min 2 chars"),
  description: z.string().optional(),
  subcapability_id: z.number().int(),
});

const PAGE_SIZE = 10;

export default function TrainingMethodPage() {
  const [methods, setMethods] = useState<TrainingMethod[]>([]);
  const [subcaps, setSubcaps] = useState<Subcapability[]>([]);
  const [query, setQuery] = useState("");
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState<TrainingMethod | null>(null);
  const [open, setOpen] = useState(false);
  const [toDelete, setToDelete] = useState<TrainingMethod | null>(null);
  const [page, setPage] = useState(1);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return methods.filter((x) => !q || x.name.toLowerCase().includes(q));
  }, [methods, query]);

  const paginated = useMemo(() => {
    const start = (page - 1) * PAGE_SIZE;
    return filtered.slice(start, start + PAGE_SIZE);
  }, [filtered, page]);

  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const rangeStart = filtered.length ? (page - 1) * PAGE_SIZE + 1 : 0;
  const rangeEnd = filtered.length
    ? Math.min(page * PAGE_SIZE, filtered.length)
    : 0;

  useEffect(() => {
    const fetch = async () => {
      const { data: subc } = await supabase
        .from("physical_subcapability")
        .select("id, name")
        .order("name", { ascending: true });

      const { data } = await supabase
        .from("training_method")
        .select("id, name, description, subcapability_id")
        .order("id", { ascending: true });

      setSubcaps(subc || []);
      setMethods(data || []);
      setLoading(false);
    };
    fetch();
  }, []);

  useEffect(() => {
    setPage(1);
  }, [query]);

  useEffect(() => {
    setPage((prev) => {
      const lastPage = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
      return Math.min(prev, lastPage);
    });
  }, [filtered.length]);

  const form = useForm<FormValues>({
    resolver: zodResolver(schema),
    defaultValues: editing
      ? {
          id: editing.id,
          name: editing.name,
          description: editing.description ?? "",
          subcapability_id: editing.subcapability_id,
        }
      : {
          name: "",
          description: "",
          subcapability_id: 1,
        },
  });

  const submit = async (values: FormValues) => {
    if (editing?.id) {
      const { error } = await supabase
        .from("training_method")
        .update({
          name: values.name,
          description: values.description,
          subcapability_id: values.subcapability_id,
        })
        .eq("id", editing.id);

      if (!error)
        setMethods((prev) =>
          prev.map((p) => (p.id === editing.id ? { ...p, ...values } : p))
        );
    } else {
      const { data, error } = await supabase
        .from("training_method")
        .insert({
          name: values.name,
          description: values.description,
          subcapability_id: values.subcapability_id,
        })
        .select()
        .single();

      if (!error && data) setMethods((prev) => [data, ...prev]);
    }
    setOpen(false);
  };

  const onDelete = async () => {
    if (!toDelete) return;

    const { error } = await supabase
      .from("training_method")
      .delete()
      .eq("id", toDelete.id);

    if (!error)
      setMethods((prev) => prev.filter((p) => p.id !== toDelete.id));

    setToDelete(null);
  };

  return (
    <div className="min-h-screen bg-slate-50 p-6">
      <div className="mx-auto max-w-4xl space-y-6">
        {/* Header */}
        <div className="flex justify-between items-center">
          <div>
            <h1 className="text-2xl font-bold">Métodos de entrenamiento</h1>
            <p className="text-muted-foreground">
              Catálogo asociado a subcapacidades físicas.
            </p>
          </div>
          <Dialog open={open} onOpenChange={setOpen}>
            <DialogTrigger asChild>
              <Button
                onClick={() => {
                  form.reset();
                  setEditing(null);
                  setOpen(true);
                }}
              >
                <Plus className="mr-2 h-4 w-4" /> Nuevo
              </Button>
            </DialogTrigger>
            <DialogContent className="sm:max-w-[450px]">
              <DialogHeader>
                <DialogTitle>
                  {editing ? "Editar método" : "Crear método"}
                </DialogTitle>
                <DialogDescription>
                  Selecciona la subcapacidad asociada.
                </DialogDescription>
              </DialogHeader>

              <form className="space-y-4" onSubmit={form.handleSubmit(submit)}>
                <div className="grid gap-2">
                  <Label htmlFor="name">Nombre</Label>
                  <Input id="name" {...form.register("name")} />
                </div>

                <div className="grid gap-2">
                  <Label htmlFor="description">Descripción</Label>
                  <Input id="description" {...form.register("description")} />
                </div>

                <div className="grid gap-2">
                  <Label htmlFor="subcapability_id">Subcapacidad</Label>
                  <select
                    id="subcapability_id"
                    {...form.register("subcapability_id", { valueAsNumber: true })}
                    className="border px-3 py-2 rounded text-sm"
                  >
                    {subcaps.map((c) => (
                      <option key={c.id} value={c.id}>
                        {c.name}
                      </option>
                    ))}
                  </select>
                </div>

                <div className="flex justify-end gap-2 pt-2">
                  <Button variant="outline" onClick={() => setOpen(false)}>
                    Cancelar
                  </Button>
                  <Button type="submit">Guardar</Button>
                </div>
              </form>
            </DialogContent>
          </Dialog>
        </div>

        {/* Search */}
        <Card>
          <CardHeader>
            <CardTitle>Búsqueda</CardTitle>
          </CardHeader>
          <CardContent>
            <Input
              placeholder="Buscar por nombre"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
            />
          </CardContent>
        </Card>

        {/* Table */}
        <Card>
          <CardHeader>
            <CardTitle>Registros</CardTitle>
          </CardHeader>
          <CardContent>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>ID</TableHead>
                  <TableHead>Nombre</TableHead>
                  <TableHead>Descripción</TableHead>
                  <TableHead>Subcapacidad</TableHead>
                  <TableHead className="text-right">Acciones</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {paginated.map((x) => (
                  <TableRow key={x.id}>
                    <TableCell>{x.id}</TableCell>
                    <TableCell>{x.name}</TableCell>
                    <TableCell>{x.description || "-"}</TableCell>
                    <TableCell>
                      {subcaps.find((s) => s.id === x.subcapability_id)?.name || "-"}
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex gap-2 justify-end">
                        <Button
                          variant="outline"
                          size="icon"
                          onClick={() => {
                            setEditing(x);
                            form.reset({ ...x, description: x.description ?? "" });
                            setOpen(true);
                          }}
                        >
                          <Pencil className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="outline"
                          size="icon"
                          onClick={() => setToDelete(x)}
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
                {filtered.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={5} className="text-center text-muted-foreground">
                      Sin resultados.
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
            <div className="flex flex-col gap-2 pt-4 text-sm text-muted-foreground sm:flex-row sm:items-center sm:justify-between">
              <p>
                Mostrando {rangeStart}-{rangeEnd} de {filtered.length} registros
              </p>
              <div className="flex items-center gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setPage((prev) => Math.max(1, prev - 1))}
                  disabled={page <= 1 || filtered.length === 0}
                >
                  Anterior
                </Button>
                <span>
                  Pagina {page} de {totalPages}
                </span>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setPage((prev) => Math.min(totalPages, prev + 1))}
                  disabled={page >= totalPages || filtered.length === 0}
                >
                  Siguiente
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Delete Dialog */}
        <AlertDialog open={!!toDelete} onOpenChange={(o) => !o && setToDelete(null)}>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Eliminar</AlertDialogTitle>
              <AlertDialogDescription>
                ¿Estás seguro de que deseas eliminar "{toDelete?.name}"?
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>Cancelar</AlertDialogCancel>
              <AlertDialogAction onClick={onDelete}>Eliminar</AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </div>
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import { z } from "zod";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow
} from "@/components/ui/table";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue
} from "@/components/ui/select";

import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";

import { Plus, Pencil, Trash2, Search } from "lucide-react";

// =====================================================
// ✅ SCHEMA
// =====================================================

const roles = ["admin", "manager", "viewer"] as const;
const statuses = ["active", "suspended"] as const;

// ✅ El tipo User ACEPTA createdAt como opcional
type User = {
  id?: string;
  name: string;
  email: string;
  role: "admin" | "manager" | "viewer";
  status: "active" | "suspended";
  createdAt?: string;
};

const userSchema = z.object({
  id: z.string().optional(),
  name: z.string().min(2),
  email: z.string().email(),
  role: z.enum(roles),
  status: z.enum(statuses),
});

// =====================================================
// ✅ MOCK DATA
// =====================================================

const initialData: User[] = [
  {
    id: "1",
    name: "Alice Mendoza",
    email: "alice@example.com",
    role: "admin",
    status: "active",
    createdAt: new Date().toISOString(),
  },
  {
    id: "2",
    name: "Carlos Ruiz",
    email: "carlos@example.com",
    role: "manager",
    status: "active",
    createdAt: new Date().toISOString(),
  },
];

// =====================================================
// ✅ PAGE COMPONENT
// =====================================================

export default function Page() {
  const [users, setUsers] = useState<User[]>(initialData);
  const [search, setSearch] = useState("");
  const [editing, setEditing] = useState<User | null>(null);
  const [openForm, setOpenForm] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState<User | null>(null);

  const filtered = useMemo(() => {
    const q = search.toLowerCase();
    return users.filter((u) =>
      `${u.name} ${u.email}`.toLowerCase().includes(q)
    );
  }, [users, search]);

  function save(user: User) {
    setUsers((prev) => {
      const exists = prev.some((p) => p.id === user.id);
      if (exists) {
        return prev.map((p) => (p.id === user.id ? user : p));
      }
      return [
        ...prev,
        {
          ...user,
          id: crypto.randomUUID(),
          createdAt: new Date().toISOString(),
        },
      ];
    });
    setOpenForm(false);
  }

  function remove(user: User) {
    setUsers((prev) => prev.filter((u) => u.id !== user.id));
    setConfirmDelete(null);
  }

  return (
    <div className="p-6 mx-auto max-w-6xl">
      <h1 className="text-3xl font-bold mb-4">User Administration</h1>

      <Card className="mb-4">
        <CardContent className="flex gap-3 py-4">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <Input
              placeholder="Search users..."
              className="pl-9"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>

          <Dialog open={openForm} onOpenChange={setOpenForm}>
            <DialogTrigger asChild>
              <Button
                onClick={() => {
                  setEditing(null);
                  setOpenForm(true);
                }}
              >
                <Plus className="mr-2 h-4 w-4" /> New User
              </Button>
            </DialogTrigger>

            <DialogContent className="max-w-lg">
              <DialogHeader>
                <DialogTitle>{editing ? "Edit User" : "Create User"}</DialogTitle>
              </DialogHeader>

              <UserForm
                initial={editing ?? undefined}
                onCancel={() => setOpenForm(false)}
                onSubmit={(u) =>
                  save({
                    ...u,
                    id: editing?.id ?? crypto.randomUUID(),
                    createdAt: editing?.createdAt ?? new Date().toISOString(),
                  })
                }
              />
            </DialogContent>
          </Dialog>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>Users</CardTitle>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Name</TableHead>
                <TableHead>Email</TableHead>
                <TableHead>Role</TableHead>
                <TableHead>Status</TableHead>
                <TableHead className="text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>

            <TableBody>
              {filtered.map((u) => (
                <TableRow key={u.id}>
                  <TableCell>{u.name}</TableCell>
                  <TableCell>{u.email}</TableCell>
                  <TableCell>
                    <Badge className="capitalize">{u.role}</Badge>
                  </TableCell>
                  <TableCell>
                    <Switch
                      checked={u.status === "active"}
                      onCheckedChange={(v) =>
                        setUsers((prev) =>
                          prev.map((x) =>
                            x.id === u.id
                              ? {
                                  ...x,
                                  status: (v
                                    ? "active"
                                    : "suspended") as User["status"],
                                }
                              : x
                          )
                        )
                      }
                    />
                  </TableCell>

                  <TableCell className="text-right flex gap-2 justify-end">
                    <Button
                      variant="outline"
                      size="icon"
                      onClick={() => {
                        setEditing(u);
                        setOpenForm(true);
                      }}
                    >
                      <Pencil className="h-4 w-4" />
                    </Button>

                    <Button
                      variant="outline"
                      size="icon"
                      onClick={() => setConfirmDelete(u)}
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </TableCell>
                </TableRow>
              ))}

              {filtered.length === 0 && (
                <TableRow>
                  <TableCell colSpan={5} className="text-center text-muted-foreground">
                    No users found.
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      {/* DELETE CONFIRMATION */}
      <AlertDialog open={!!confirmDelete} onOpenChange={() => setConfirmDelete(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete user</AlertDialogTitle>
            <AlertDialogFooter>
              <AlertDialogCancel>Cancel</AlertDialogCancel>
              <AlertDialogAction
                onClick={() => confirmDelete && remove(confirmDelete)}
              >
                Delete
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogHeader>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

// =====================================================
// ✅ USER FORM
// =====================================================

function UserForm({
  initial,
  onCancel,
  onSubmit,
}: {
  initial?: User;
  onCancel: () => void;
  onSubmit: (u: User) => void;
}) {
  const form = useForm<User>({
    resolver: zodResolver(userSchema),
    defaultValues: initial ?? ({
      name: "",
      email: "",
      role: "viewer",
      status: "active",
    } as User),
  });

  return (
    <form className="space-y-4" onSubmit={form.handleSubmit(onSubmit)}>
      <div>
        <Label>Name</Label>
        <Input {...form.register("name")} />
      </div>

      <div>
        <Label>Email</Label>
        <Input type="email" {...form.register("email")} />
      </div>

      <div>
        <Label>Role</Label>
        <Select
          value={form.watch("role")}
          onValueChange={(v) => form.setValue("role", v as User["role"])}
        >
          <SelectTrigger><SelectValue /></SelectTrigger>
          <SelectContent>
            {roles.map((r) => (
              <SelectItem key={r} value={r}>{r}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <div>
        <Label>Status</Label>
        <Select
          value={form.watch("status")}
          onValueChange={(v) => form.setValue("status", v as User["status"])}
        >
          <SelectTrigger><SelectValue /></SelectTrigger>
          <SelectContent>
            {statuses.map((s) => (
              <SelectItem key={s} value={s}>{s}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <div className="flex justify-end gap-2">
        <Button variant="outline" type="button" onClick={onCancel}>
          Cancel
        </Button>
        <Button type="submit">Save</Button>
      </div>
    </form>
  );
}

